BEGIN;
SET LOCAL ROLE service_role;
DO $$
DECLARE actor uuid:=gen_random_uuid(); member_user uuid:=gen_random_uuid(); member uuid; viewer uuid; visible uuid; hidden uuid; short_id uuid; key_id uuid; entity uuid:=gen_random_uuid(); result jsonb; metadata jsonb; version uuid; tag uuid; manifest jsonb:='[{"id":"static:/old:/new:301:0","source":"/old","target":"/new","origin":"public/_redirects","kind":"Static","statusCode":301,"state":"Enabled","updatedAt":null},{"id":"client:fixture","source":"/me","target":"/user/:currentUserId (or /auth)","origin":"Client router","kind":"Client","statusCode":null,"state":"Enabled","updatedAt":null}]';
BEGIN
 INSERT INTO auth.users(id) VALUES(actor),(member_user);INSERT INTO public.user_roles VALUES(actor,'admin');
 INSERT INTO public.redirect_workspace_members(user_id,kind,label) VALUES(member_user,'user','Inventory editor') RETURNING id INTO member;
 INSERT INTO public.redirect_workspace_members(kind,label,role) VALUES('machine','Inventory viewer','viewer') RETURNING id INTO viewer;
 INSERT INTO public.redirect_link_folders(name,default_permission) VALUES('Visible aliases','view') RETURNING id INTO visible;
 INSERT INTO public.redirect_link_folders(name,default_permission) VALUES('Hidden aliases','none') RETURNING id INTO hidden;
 INSERT INTO public.venues(id,slug) VALUES(entity,'current-venue');
 INSERT INTO public.venue_slug_redirects(old_slug,venue_id) VALUES('old-venue',entity);
 INSERT INTO public.redirects(type,slug,target) VALUES('SHORT','inventory-short','/events') RETURNING id INTO short_id;
 INSERT INTO public.redirects(type,source_path,target) VALUES('PATH','/old-path','/new-path');
 INSERT INTO public.username_redirects(old_username,user_id,expires_at) VALUES('old-account',member_user,now()-interval '1 day');
 INSERT INTO public.redirect_link_tags(name) VALUES('Inventory tag') RETURNING id INTO tag;
 result:=public.redirect_inventory_page(manifest);
 IF (result->>'count')::int<>6 OR jsonb_array_length(result->'data')<>6 THEN RAISE EXCEPTION 'All-source count omitted records: %',result;END IF;
 result:=public.redirect_inventory_page(manifest,'{"excludeManaged":true}');
 IF (result->>'count')::int<>5 THEN RAISE EXCEPTION 'Other-source filter failed';END IF;
 result:=public.redirect_inventory_page(manifest,'{}',1);
 IF result->>'nextCursor' IS NULL OR jsonb_array_length(result->'data')<>1 THEN RAISE EXCEPTION 'Inventory pagination failed';END IF;
 IF public.redirect_inventory_page(manifest,'{}',100,result->>'nextCursor')->>'count'<>'6' THEN RAISE EXCEPTION 'Inventory page count changed';END IF;
 metadata:=public.redirect_inventory_metadata(manifest,'venue_slug_redirects:old-venue');
 IF metadata->'metadataVersion'<>'null' OR metadata->>'comment'<>'' THEN RAISE EXCEPTION 'Initial metadata was fabricated';END IF;
 metadata:=public.redirect_inventory_metadata(manifest,'venue_slug_redirects:old-venue',jsonb_build_object('comment','Private alias note','folderId',hidden,'tagIds',jsonb_build_array(tag)));
 version:=(metadata->>'metadataVersion')::uuid;
 IF metadata->>'comment'<>'Private alias note' OR version IS NULL THEN RAISE EXCEPTION 'Alias metadata save failed';END IF;
 result:=public.redirect_inventory_page(manifest,'{}',100,NULL,member);
 IF (result->>'count')::int<>5 OR EXISTS(SELECT FROM jsonb_array_elements(result->'data') r WHERE r->>'id'='venue_slug_redirects:old-venue') THEN RAISE EXCEPTION 'Hidden alias disclosed';END IF;
 BEGIN PERFORM public.redirect_inventory_metadata(manifest,'venue_slug_redirects:old-venue',p_principal=>member);RAISE EXCEPTION 'Hidden alias detail disclosed';EXCEPTION WHEN no_data_found THEN NULL;END;
 BEGIN PERFORM public.redirect_inventory_metadata(manifest,'missing:key',p_principal=>member);RAISE EXCEPTION 'Missing record fabricated';EXCEPTION WHEN no_data_found THEN NULL;END;
 metadata:=public.redirect_inventory_metadata(manifest,'venue_slug_redirects:old-venue',jsonb_build_object('folderId',visible),version);
 version:=(metadata->>'metadataVersion')::uuid;
 BEGIN PERFORM public.redirect_inventory_metadata(manifest,'venue_slug_redirects:old-venue','{"comment":"denied"}',version,member);RAISE EXCEPTION 'View-only alias edited';EXCEPTION WHEN no_data_found THEN NULL;END;
 INSERT INTO public.redirect_folder_members VALUES(visible,member,'edit');
 metadata:=public.redirect_inventory_metadata(manifest,'venue_slug_redirects:old-venue','{"comment":"Allowed alias edit"}',version,member);
 BEGIN PERFORM public.redirect_inventory_metadata(manifest,'venue_slug_redirects:old-venue','{"comment":"stale"}',version,member);RAISE EXCEPTION 'Stale metadata overwritten';EXCEPTION WHEN unique_violation THEN NULL;END;
 version:=(metadata->>'metadataVersion')::uuid;
 BEGIN PERFORM public.redirect_inventory_metadata(manifest,'venue_slug_redirects:old-venue',jsonb_build_object('folderId',hidden),version,member);RAISE EXCEPTION 'Moved into inaccessible folder';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.redirect_inventory_metadata(manifest,'venue_slug_redirects:old-venue','{"target":"https://evil.example.org"}',version,member);RAISE EXCEPTION 'Routing target mutated';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 IF (SELECT e.slug FROM public.venues e WHERE e.id=entity)<>'current-venue' OR (SELECT venue_id FROM public.venue_slug_redirects WHERE old_slug='old-venue')<>entity THEN RAISE EXCEPTION 'Underlying routing changed';END IF;
 result:=public.redirect_inventory_organize(manifest,jsonb_build_array(jsonb_build_object('id','static:/old:/new:301:0','version',NULL,'values',jsonb_build_object('comment','static metadata'))),member);
 IF result#>>'{data,0,comment}'<>'static metadata' THEN RAISE EXCEPTION 'Static metadata edit failed';END IF;
 BEGIN PERFORM public.redirect_inventory_organize(manifest,jsonb_build_array(jsonb_build_object('id','client:fixture','version',NULL,'values',jsonb_build_object('comment','rollback')),jsonb_build_object('id','missing:key','version',NULL,'values',jsonb_build_object('comment','denied'))),member);RAISE EXCEPTION 'Invalid mixed bulk committed';EXCEPTION WHEN no_data_found THEN NULL;END;
 IF EXISTS(SELECT FROM public.redirect_link_metadata WHERE redirect_key='client:fixture') THEN RAISE EXCEPTION 'Bulk left partial metadata';END IF;
 INSERT INTO public.redirect_api_tokens(name,token_hash,prefix,scopes,redirect_ids,created_by,expires_at) VALUES('Selected inventory',repeat('7',64),'fixture',ARRAY['links:read','links:write'],ARRAY[short_id],actor,now()+interval '1 day') RETURNING id INTO key_id;
 result:=public.redirect_inventory_page(manifest,'{}',100,NULL,key_id);
 IF (result->>'count')::int<>1 OR result#>>'{data,0,id}'<>'redirects:'||short_id::text THEN RAISE EXCEPTION 'Selected key escaped source scope';END IF;
 UPDATE public.redirect_api_tokens SET member_id=viewer,redirect_ids=NULL WHERE id=key_id;
 result:=public.redirect_inventory_page(manifest,'{}',100,NULL,key_id);
 IF EXISTS(SELECT FROM jsonb_array_elements(result->'data') r WHERE (r->>'canEditMetadata')::boolean) THEN RAISE EXCEPTION 'Workspace viewer edit capability';END IF;
 UPDATE public.redirect_workspace_members SET active=false WHERE id=viewer;
 BEGIN PERFORM public.redirect_inventory_page(manifest,'{}',100,NULL,key_id);RAISE EXCEPTION 'Inactive member inventory allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END $$;
RESET ROLE;
SET LOCAL ROLE authenticated;
DO $$ BEGIN
 IF has_table_privilege(current_user,'public.redirect_inventory_database','select') OR has_function_privilege(current_user,'public.redirect_inventory_page(jsonb,jsonb,integer,text,uuid)','execute') THEN RAISE EXCEPTION 'Private inventory exposed directly';END IF;
END $$;
ROLLBACK;
